use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl Symbol { # [doc = " Avoid this except for things like deserialization of previously"] # [doc = " serialized symbols, and testing. Use `intern` instead."] pub const fn new (n : u32) -> Self { Symbol (SymbolIndex :: from_u32 (n)) } # [doc = " Maps a string to its interned representation."] # [rustc_diagnostic_item = "SymbolIntern"] pub fn intern (str : & str) -> Self { with_session_globals (| session_globals | session_globals . symbol_interner . intern_str (str)) } # [doc = " Access the underlying string. This is a slowish operation because it"] # [doc = " requires locking the symbol interner."] # [doc = ""] # [doc = " Note that the lifetime of the return value is a lie. It's not the same"] # [doc = " as `&self`, but actually tied to the lifetime of the underlying"] # [doc = " interner. Interners are long-lived, and there are very few of them, and"] # [doc = " this function is typically used for short-lived things, so in practice"] # [doc = " it works out ok."] pub fn as_str (& self) -> & str { with_session_globals (| session_globals | unsafe { std :: mem :: transmute :: < & str , & str > (session_globals . symbol_interner . get_str (* self)) }) } pub fn as_u32 (self) -> u32 { self . 0 . as_u32 () } pub fn is_empty (self) -> bool { self == sym :: empty } # [doc = " This method is supposed to be used in error messages, so it's expected to be"] # [doc = " identical to printing the original identifier token written in source code"] # [doc = " (`token_to_string`, `Ident::to_string`), except that symbols don't keep the rawness flag"] # [doc = " or edition, so we have to guess the rawness using the global edition."] pub fn to_ident_string (self) -> String { if self == sym :: empty { String :: new () } else { Ident :: with_dummy_span (self) . to_string () } } }
}